import{c as o,Q as r,j as a,m as t}from"./chunks/framework.DGHXLY8X.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function n(s,e,d,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Generated at build time from <a href="https://github.com/smazurov/videonode/blob/main/changelog.yml" target="_blank" rel="noreferrer"><code>changelog.yml</code></a>. Cross-reference <a href="https://github.com/smazurov/videonode/releases" target="_blank" rel="noreferrer">GitHub Releases</a> for download links and signed artifacts.</p><h2 id="_4-2-0" tabindex="-1">4.2.0 <a class="header-anchor" href="#_4-2-0" aria-label="Permalink to &quot;4.2.0&quot;">​</a></h2><p><em>2026-08-30</em></p><ul><li>Stream recording writes H264 or H265 video to keyframe-aligned fMP4/HLS segments without a second encode; the new recording UI supports live playback, poster frames, storyboard hover previews, filmstrip seeking, session size and duration, and start/stop/delete controls (<a href="https://github.com/smazurov/videonode/commit/485db82" target="_blank" rel="noreferrer"><code>485db82</code></a>)</li><li>Recording sessions now finalize cleanly after write failures, producer replacement, or shutdown; same-second restarts no longer overwrite earlier sessions, active storyboard images avoid stale browser caches, and reported size and duration include the final flushed segment (<a href="https://github.com/smazurov/videonode/commit/393f481" target="_blank" rel="noreferrer"><code>393f481</code></a>)</li><li>Sources can run a shell command that emits yuv4mpegpipe frames; VideoNode reads geometry and frame rate from the Y4M header, reports the detected format to dependent encoders, falls back to NO SIGNAL on EOF, and retries the command once per second (<a href="https://github.com/smazurov/videonode/commit/6e70147" target="_blank" rel="noreferrer"><code>6e70147</code></a>)</li><li>Staged source frames are exported through udmabuf before GPU import, fixing black composer slots when the source uses cached memfd-backed buffers and making import failures visible in the log (<a href="https://github.com/smazurov/videonode/commit/5d69332" target="_blank" rel="noreferrer"><code>5d69332</code></a>)</li><li>Composer inputs reconnect after a source process restarts instead of freezing on the last frame; retries are non-blocking and limited to once per second per slot (<a href="https://github.com/smazurov/videonode/commit/0784f23" target="_blank" rel="noreferrer"><code>0784f23</code></a>)</li><li>Composer output preserves red and blue correctly during BGRA-to-NV12 conversion, fixing swapped colors in canvas snapshots, SCM broadcasts, and downstream streams (<a href="https://github.com/smazurov/videonode/commit/90ec17d" target="_blank" rel="noreferrer"><code>90ec17d</code></a>)</li><li>Linux password authentication now runs through the packaged videonode-session PAM helper; the daemon and its child processes no longer inherit shadow-group access, and upgrades revoke the old membership (<a href="https://github.com/smazurov/videonode/commit/d06dbaf" target="_blank" rel="noreferrer"><code>d06dbaf</code></a>)</li><li>SSE event delivery no longer leaves 2 kHz dispatcher goroutines behind after clients disconnect, removing the measured 16 to 20 percent idle CPU load on RK3588 after the first UI connection (<a href="https://github.com/smazurov/videonode/commit/d72b7f7" target="_blank" rel="noreferrer"><code>d72b7f7</code></a>)</li><li>A composer&#39;s video coverage can be exported as an OBS alpha mask from the composer and stream pages, so the canvas layers over other scene content instead of arriving as one opaque rectangle; download a canvas-sized PNG for the Image Mask/Blend filter, or copy a browser-source URL whose player clips the live video to the same regions with no OBS plugin (<a href="https://github.com/smazurov/videonode/commit/2329b0c" target="_blank" rel="noreferrer"><code>2329b0c</code></a>)</li></ul><h2 id="_4-1-1" tabindex="-1">4.1.1 <a class="header-anchor" href="#_4-1-1" aria-label="Permalink to &quot;4.1.1&quot;">​</a></h2><p><em>2026-06-09</em></p><ul><li>SRT egress improvements for H265: subscribers joining between keyframes now get VPS/SPS/PPS prepended so the decoder starts immediately instead of stalling until the next IDR; the listener also gains tunable latency/bandwidth/idle-timeout knobs and aligns its payload to 1316 bytes (7x188) so MPEG-TS packets stay intact (<a href="https://github.com/smazurov/videonode/commit/37ff943" target="_blank" rel="noreferrer"><code>37ff943</code></a>)</li></ul><h2 id="_4-1-0" tabindex="-1">4.1.0 <a class="header-anchor" href="#_4-1-0" aria-label="Permalink to &quot;4.1.0&quot;">​</a></h2><p><em>2026-06-08</em></p><ul><li>Processes panel rebuilt on a dedicated SSE process stream — live per-process stats pushed instead of polled, with explicit process-removed events; the UI fetches once on start/reconnect, then follows pushes (<a href="https://github.com/smazurov/videonode/commit/6d32de6" target="_blank" rel="noreferrer"><code>6d32de6</code></a>)</li><li>the daemon now appears as its own self row with live CPU/RSS, the InfoBar derives its stats from the processes stream (dropping /api/system), and host GPU/MPP/NPU utilization is surfaced alongside (<a href="https://github.com/smazurov/videonode/commit/897d5fd" target="_blank" rel="noreferrer"><code>897d5fd</code></a>)</li><li>source capture hardened — zero-copy dma-heap DMABUF capture, a libplacebo CSC fallback when RGA can&#39;t convert NV24, 64B NV12 stride padding, and steadier behavior through signal loss and HDMI link flaps; the v1-&gt;v2 config migration and migrate-config command are gone, so streams.toml must already be version 2 (<a href="https://github.com/smazurov/videonode/commit/820265a" target="_blank" rel="noreferrer"><code>820265a</code></a>)</li><li>smaller operational fixes: auth falls back to Basic when /etc/shadow is unreadable, WHEP DELETE is idempotent for an already-closed peer, and an opt-in net/http/pprof debug server for live profiling (<a href="https://github.com/smazurov/videonode/commit/519fcb9" target="_blank" rel="noreferrer"><code>519fcb9</code></a>)</li></ul><h2 id="_4-0-0" tabindex="-1">4.0.0 <a class="header-anchor" href="#_4-0-0" aria-label="Permalink to &quot;4.0.0&quot;">​</a></h2><p><em>2026-06-03</em></p><ul><li>new pipeline architecture: sources, composers, and streams are three independent top-level entities wired by explicit upstream refs, governed by a single pipeline master switch, with encoders that spawn lazily on the first reader and stop after the last (<a href="https://github.com/smazurov/videonode/commit/b22080f" target="_blank" rel="noreferrer"><code>b22080f</code></a>)</li><li>native RK3588 media pipeline: videonode-source/composer/sink processes move NV12 dma-bufs zero-copy over SCM_RIGHTS, with a libplacebo GPU compositor and an NV12-end-to-end path carrying colorimetry through to the encoder (<a href="https://github.com/smazurov/videonode/commit/1a42a4d" target="_blank" rel="noreferrer"><code>1a42a4d</code></a>)</li><li>GPU composer with a live layout editor: multi-source compositing onto a canvas, a Region/Content model with per-slot rotation, crop, pan/zoom and fit, per-input perspective effects, configurable background, and edits that apply without restarting the pipeline — plus composer config TOML export/import (<a href="https://github.com/smazurov/videonode/commit/c1a4d04" target="_blank" rel="noreferrer"><code>c1a4d04</code></a>)</li><li>WebRTC playback via a WHEP egress endpoint with H265, fanning out alongside SRT and RTSP from the built-in local relay (<a href="https://github.com/smazurov/videonode/commit/f412934" target="_blank" rel="noreferrer"><code>f412934</code></a>)</li><li>RK3588 hardware acceleration end to end: hardware MJPEG decode through MPP, rkmpp encoders ingesting BGRA/RGB directly, and an S32_LE-capable audio capture path for the on-board ADC (<a href="https://github.com/smazurov/videonode/commit/cea24f4" target="_blank" rel="noreferrer"><code>cea24f4</code></a>)</li><li>rebuilt operational web UI on a single typed SSE entity stream: live pipeline/source/stream stats and sparklines, per-entity log panels, consumer counts and client IPs, process restart controls, an embedded WHEP player, and dead-rig detection (<a href="https://github.com/smazurov/videonode/commit/22fbdd1" target="_blank" rel="noreferrer"><code>22fbdd1</code></a>)</li><li>unified .deb packaging with a GitHub Pages APT repo, shadow-group-gated auth with postinst enrollment, and service auto-start on install — replacing goreleaser, the in-app self-update service, and install.sh (<a href="https://github.com/smazurov/videonode/commit/55a842b" target="_blank" rel="noreferrer"><code>55a842b</code></a>)</li><li>VitePress documentation site with Mermaid diagrams, search, and versioned navigation (<a href="https://github.com/smazurov/videonode/commit/cdd37c1" target="_blank" rel="noreferrer"><code>cdd37c1</code></a>)</li></ul><h2 id="_4-0-0-rc12" tabindex="-1">4.0.0-rc12 <a class="header-anchor" href="#_4-0-0-rc12" aria-label="Permalink to &quot;4.0.0-rc12&quot;">​</a></h2><p><em>2026-05-31</em></p><ul><li>MJPEG sources with 4:2:2/4:4:4 chroma (e.g. HDMI-USB capture dongles) no longer show a red color ghost — the source converts them to NV12 instead of mislabeling the decode (<a href="https://github.com/smazurov/videonode/commit/0df70cf" target="_blank" rel="noreferrer"><code>0df70cf</code></a>)</li></ul><h2 id="_4-0-0-rc11" tabindex="-1">4.0.0-rc11 <a class="header-anchor" href="#_4-0-0-rc11" aria-label="Permalink to &quot;4.0.0-rc11&quot;">​</a></h2><p><em>2026-05-31</em></p><ul><li>composer pipeline goes NV12 end-to-end: GPU NV12 canvas output, NV12 composer inputs, an NV12-only sink carrier, and snapshots that read the staged NV12 fds, with colorimetry/VUI tags carried through (<a href="https://github.com/smazurov/videonode/commit/8ed71b8" target="_blank" rel="noreferrer"><code>8ed71b8</code></a>)</li><li>zero-copy canvas broadcast gated on per-consumer read completion, plus a GPU canvas clear and depth-4 ring, cutting per-frame CPU on the compositor (<a href="https://github.com/smazurov/videonode/commit/7746e7b" target="_blank" rel="noreferrer"><code>7746e7b</code></a>)</li><li>UI surfaces the detected source colorimetry, and the stream audio config now lays out on a single line (<a href="https://github.com/smazurov/videonode/commit/4057bcb" target="_blank" rel="noreferrer"><code>4057bcb</code></a>)</li><li>composer config exports to and imports from TOML — copy-paste in the browser or a .toml file, including overwriting an existing composer in place (<a href="https://github.com/smazurov/videonode/commit/9069dd2" target="_blank" rel="noreferrer"><code>9069dd2</code></a>)</li><li>pipeline start is best-effort so one failing stage no longer blocks the rest; the composer also clears a stuck snapshot request on RPC timeout (<a href="https://github.com/smazurov/videonode/commit/ba2024f" target="_blank" rel="noreferrer"><code>ba2024f</code></a>)</li><li>journald logging de-noised: dedup is keyed on the full record rather than message text, and the packaged service no longer double-logs to the journal (<a href="https://github.com/smazurov/videonode/commit/2403997" target="_blank" rel="noreferrer"><code>2403997</code></a>)</li></ul><h2 id="_4-0-0-rc10" tabindex="-1">4.0.0-rc10 <a class="header-anchor" href="#_4-0-0-rc10" aria-label="Permalink to &quot;4.0.0-rc10&quot;">​</a></h2><p><em>2026-05-31</em></p><ul><li>rkmpp encoders ingest BGRA/RGB32 directly, converting in hardware instead of via a CPU-heavy software nv12 filter (<a href="https://github.com/smazurov/videonode/commit/7e869b2" target="_blank" rel="noreferrer"><code>7e869b2</code></a>)</li><li>readers dialing a stream that isn&#39;t configured now get a clean 404 instead of a logged warning and a spawned encoder (<a href="https://github.com/smazurov/videonode/commit/89b821e" target="_blank" rel="noreferrer"><code>89b821e</code></a>)</li><li>the .deb ships the videonode asound.conf so the RK3588 audio capture config is present on install (<a href="https://github.com/smazurov/videonode/commit/e533874" target="_blank" rel="noreferrer"><code>e533874</code></a>)</li></ul><h2 id="_4-0-0-rc9" tabindex="-1">4.0.0-rc9 <a class="header-anchor" href="#_4-0-0-rc9" aria-label="Permalink to &quot;4.0.0-rc9&quot;">​</a></h2><p><em>2026-05-31</em></p><ul><li>WHEP egress endpoint (POST/DELETE /whep/{stream}) for WebRTC playback, with working H265 and a fix for motion smearing (<a href="https://github.com/smazurov/videonode/commit/f412934" target="_blank" rel="noreferrer"><code>f412934</code></a>)</li><li>WebRTC peers and SRT consumers now share a single hex client-ID scheme (<a href="https://github.com/smazurov/videonode/commit/cde5b5c" target="_blank" rel="noreferrer"><code>cde5b5c</code></a>)</li></ul><h2 id="_4-0-0-rc8" tabindex="-1">4.0.0-rc8 <a class="header-anchor" href="#_4-0-0-rc8" aria-label="Permalink to &quot;4.0.0-rc8&quot;">​</a></h2><p><em>2026-05-30</em></p><ul><li>RK3588 audio capture reworked: routed through an mmap plug-&gt;dsnoop PCM that converts the card-native format (the Hollyland Lyra is S32_LE-only) to whatever the encoder requests, with a larger dsnoop ring to kill xruns under the 1080p60 transcode load (opus output ~8kbps silence -&gt; ~85kbps); the service unit gains the audio group and streams now honor per-stream audio config (<a href="https://github.com/smazurov/videonode/commit/de9c2d1" target="_blank" rel="noreferrer"><code>de9c2d1</code></a>)</li><li>native source/sink robustness: the source gates NV12 ring reuse on consumer read-completion (per-slot refcount + generation), fixing the venetian-blind tearing seen across snapshot, composer, and encoder output; vn-sink reconnects across a source/composer restart instead of feeding a dead RTSP relay; the composer fails fast on a GPU-less host (<a href="https://github.com/smazurov/videonode/commit/661e15c" target="_blank" rel="noreferrer"><code>661e15c</code></a>)</li><li>hardware MJPEG decode adopts MPP&#39;s info-change handshake (two buffer groups, packet-owned input, one-shot SET_INFO_CHANGE_READY), fixing the per-frame jpegd reset that left Lyra MJPEG frames undecoded (<a href="https://github.com/smazurov/videonode/commit/975e2d3" target="_blank" rel="noreferrer"><code>975e2d3</code></a>)</li><li>SSE entity payload is typed end-to-end as a oneOf+discriminator keyed on a <code>type</code> tag, so the UI narrows on event.type with no casts; idle now publishes a full zeroed status, so partial payloads can no longer crash the source panel (<a href="https://github.com/smazurov/videonode/commit/56558e4" target="_blank" rel="noreferrer"><code>56558e4</code></a>)</li><li>connection robustness: the UI detects a dead rig in ~20s via an 8s request timeout and a 20s SSE heartbeat watchdog instead of waiting out the TCP timeout, the shared SSE connection persists across navigation, reconnect is health-gated, and offline stats blank to dimmed em-dashes instead of frozen fake-ticking values (<a href="https://github.com/smazurov/videonode/commit/02dcb7a" target="_blank" rel="noreferrer"><code>02dcb7a</code></a>)</li><li>unified POST /api/processes/{id}/restart for source/composer/encoder, with restart buttons on the detail pages (<a href="https://github.com/smazurov/videonode/commit/3b5bfba" target="_blank" rel="noreferrer"><code>3b5bfba</code></a>)</li><li>the .deb no longer hard-depends on out-of-band board libraries (librga2, librockchip-mpp1) that come from a 3rd-party repo or a from-source build, fixing uninstallable &#39;apt install videonode&#39; where no owning package exists (<a href="https://github.com/smazurov/videonode/commit/c38e3bc" target="_blank" rel="noreferrer"><code>c38e3bc</code></a>)</li></ul><h2 id="_4-0-0-rc7" tabindex="-1">4.0.0-rc7 <a class="header-anchor" href="#_4-0-0-rc7" aria-label="Permalink to &quot;4.0.0-rc7&quot;">​</a></h2><p><em>2026-05-29</em></p><ul><li>composer layout editor rebuilt on a Region/Content model: Region is the axis-aligned output rectangle, Content the rotatable source overlay (0/90/180/270, cover/fit/stretch, pan/zoom), fixing rotated-slot resize at the root; edits now persist while the pipeline is idle (<a href="https://github.com/smazurov/videonode/commit/c1a4d04" target="_blank" rel="noreferrer"><code>c1a4d04</code></a>)</li><li>real-time updates collapse onto a single entity-envelope SSE stream, replacing the legacy per-event publishes; consumer-set changes fire a dedicated source.consumers event only on membership change (<a href="https://github.com/smazurov/videonode/commit/8275702" target="_blank" rel="noreferrer"><code>8275702</code></a>)</li><li>operational UI: infobar shows live pipeline uptime/CPU/mem via a new daemon resource endpoint, source list shows format/res/fps and live consumer count, and the header tints with no thrown errors when the backend connection drops (<a href="https://github.com/smazurov/videonode/commit/22fbdd1" target="_blank" rel="noreferrer"><code>22fbdd1</code></a>)</li><li>hardware MJPEG decode now works, driven through MPP&#39;s advanced 1-in-1-out path with input-buffer sync (the prior simple-API loop never produced a frame); adds an mpp-jpeg-probe diagnostic (<a href="https://github.com/smazurov/videonode/commit/cea24f4" target="_blank" rel="noreferrer"><code>cea24f4</code></a>)</li><li>source/capture robustness: reports no-signal when the device is absent, stops busy-spinning on capture-fd errors, stamps status with wall-clock time, and keeps the encoder idle until a reader connects (rebuilding it on a dimension change) (<a href="https://github.com/smazurov/videonode/commit/4b21ceb" target="_blank" rel="noreferrer"><code>4b21ceb</code></a>)</li><li>release target moves to Debian 13 (trixie) so the composer libplacebo backend builds; .deb runtime deps are derived from the real binaries via dpkg-shlibdeps, and installs on bookworm now fail with a readable apt error (<a href="https://github.com/smazurov/videonode/commit/7720917" target="_blank" rel="noreferrer"><code>7720917</code></a>)</li></ul><h2 id="_4-0-0-rc6" tabindex="-1">4.0.0-rc6 <a class="header-anchor" href="#_4-0-0-rc6" aria-label="Permalink to &quot;4.0.0-rc6&quot;">​</a></h2><p><em>2026-05-29</em></p><ul><li>arm64 .deb builds on Debian bookworm and declares its native runtime libraries (gRPC, protobuf, abseil, libplacebo, turbojpeg), fixing missing-shared-object and GLIBCXX-version failures on bookworm/Armbian SBCs (<a href="https://github.com/smazurov/videonode/commit/0e467ef" target="_blank" rel="noreferrer"><code>0e467ef</code></a>)</li></ul><h2 id="_4-0-0-rc5" tabindex="-1">4.0.0-rc5 <a class="header-anchor" href="#_4-0-0-rc5" aria-label="Permalink to &quot;4.0.0-rc5&quot;">​</a></h2><p><em>2026-05-28</em></p><ul><li>streams drop configurable publish targets: encoders publish to the built-in local RTSP relay, SRT/WebRTC fan out from there (breaking) (<a href="https://github.com/smazurov/videonode/commit/3ccdfaf" target="_blank" rel="noreferrer"><code>3ccdfaf</code></a>)</li><li>remove the in-app self-update service; updates ship via the .deb / APT repo only (breaking) (<a href="https://github.com/smazurov/videonode/commit/1de2fe0" target="_blank" rel="noreferrer"><code>1de2fe0</code></a>)</li><li>sources expose a liveness signal distinct from status, surfaced with per-entity log panels over the shared SSE stream (<a href="https://github.com/smazurov/videonode/commit/d5d9270" target="_blank" rel="noreferrer"><code>d5d9270</code></a>)</li><li>stream editing UI: partial-PATCH edits and auto-start preview that wakes an idle stream (<a href="https://github.com/smazurov/videonode/commit/4676230" target="_blank" rel="noreferrer"><code>4676230</code></a>)</li><li>pipeline fixes: compositor honors the NV12 UV-plane offset, source pins and reports the real capture rate via G_PARM (<a href="https://github.com/smazurov/videonode/commit/47767b1" target="_blank" rel="noreferrer"><code>47767b1</code></a>)</li><li>packaging cleanup: drop the legacy install.sh and the network-online unit dependency (<a href="https://github.com/smazurov/videonode/commit/321b127" target="_blank" rel="noreferrer"><code>321b127</code></a>)</li></ul><h2 id="_4-0-0-rc4" tabindex="-1">4.0.0-rc4 <a class="header-anchor" href="#_4-0-0-rc4" aria-label="Permalink to &quot;4.0.0-rc4&quot;">​</a></h2><p><em>2026-05-28</em></p><ul><li>packaging: enroll SUDO_USER on upgrade, not just first install (<a href="https://github.com/smazurov/videonode/commit/37f0656" target="_blank" rel="noreferrer"><code>37f0656</code></a>)</li></ul><h2 id="_4-0-0-rc3" tabindex="-1">4.0.0-rc3 <a class="header-anchor" href="#_4-0-0-rc3" aria-label="Permalink to &quot;4.0.0-rc3&quot;">​</a></h2><p><em>2026-05-27</em></p><ul><li>VitePress docs site with Mermaid, search, versioned navbar (<a href="https://github.com/smazurov/videonode/commit/cdd37c1" target="_blank" rel="noreferrer"><code>cdd37c1</code></a>)</li><li>release pipeline rewrite: matrix build replaces goreleaser, chglog-driven .deb (<a href="https://github.com/smazurov/videonode/commit/feff078" target="_blank" rel="noreferrer"><code>feff078</code></a>)</li><li>shadow-group-gated auth + postinst enrollment, service auto-start on install (<a href="https://github.com/smazurov/videonode/commit/f62e5a3" target="_blank" rel="noreferrer"><code>f62e5a3</code></a>)</li><li>composer UI: auto-slot on input add, canvas rotation moved to inspector (<a href="https://github.com/smazurov/videonode/commit/74749ac" target="_blank" rel="noreferrer"><code>74749ac</code></a>)</li><li>source reports placeholder dims while V4L2 inactive (<a href="https://github.com/smazurov/videonode/commit/16f5389" target="_blank" rel="noreferrer"><code>16f5389</code></a>)</li></ul><h2 id="_4-0-0-rc1" tabindex="-1">4.0.0-rc1 <a class="header-anchor" href="#_4-0-0-rc1" aria-label="Permalink to &quot;4.0.0-rc1&quot;">​</a></h2><p><em>2026-05-27</em></p><ul><li>feat(packaging): unified .deb via nfpm + GitHub Pages APT repo (<a href="https://github.com/smazurov/videonode/commit/c57d69e" target="_blank" rel="noreferrer"><code>c57d69e</code></a>)</li><li>refactor(packaging): replace CPack with nfpm (<a href="https://github.com/smazurov/videonode/commit/72c5d66" target="_blank" rel="noreferrer"><code>72c5d66</code></a>)</li></ul><h2 id="_3-1-0" tabindex="-1">3.1.0 <a class="header-anchor" href="#_3-1-0" aria-label="Permalink to &quot;3.1.0&quot;">​</a></h2><p><em>2026-05-18</em></p><ul><li>feat: v3.1.0 release (<a href="https://github.com/smazurov/videonode/commit/676bf30" target="_blank" rel="noreferrer"><code>676bf30</code></a>)</li></ul>',50)])])}const u=o(i,[["render",n]]);export{p as __pageData,u as default};
